// b196_sysmon_guard.sv: the PL system monitor (SYSMONE4) configured by its INIT attributes, and the latched shutdown it drives (brief 196).
// The alarm thresholds are not typed here: rtl/b196_sysmon_pkg.sv is generated by `python -m flow.security sysmon-init` from the board's
// operating limits (boards/<board>/board.yaml, operating_limits) and the build check recomputes the same values from the board file.
// Alarms used: ALM[0] temperature above its limit, ALM[1] VCCINT outside its window, ALM[2] VCCAUX outside, ALM[3] VCCBRAM outside, and OT (the
// device's own over-temperature output at its default limit: the user OT limit is not set, because setting it also enables the automatic
// device shutdown, which de-configures the part; see docs/security.md). The PS supply alarms and the user-supply alarms are disabled.
// The DRP port is tied off: the fabric never reads or writes the monitor. Simulation: SYSMONE4 is a synthesis-only instance here (the
// unisim model needs a stimulus file); `sim_alarm` stands in for the alarm bits so the latch can be tested.
module b196_sysmon_guard
    import b196_sysmon_pkg::*;
(
    input  logic       clk,            // DCLK; ADCCLK = DCLK / 8 (INIT_42), 3.125 MHz at 25 MHz
    input  logic       rst,            // synchronous, active high
    input  logic [4:0] sim_alarm,      // simulation only: {OT, ALM3, ALM2, ALM1, ALM0}; ignored in synthesis
    output logic       shutdown,
    output logic [4:0] cause
);
    logic [4:0] alarm;
`ifdef SYNTHESIS
    logic [15:0] alm;
    logic        ot;
    SYSMONE4 #(
        .SIM_MONITOR_FILE("none"), .SIM_DEVICE("ZYNQ_ULTRASCALE"),
        .INIT_41(SM_INIT_41), .INIT_42(SM_INIT_42), .INIT_43(SM_INIT_43), .INIT_48(SM_INIT_48),
        .INIT_50(SM_INIT_50), .INIT_51(SM_INIT_51), .INIT_52(SM_INIT_52), .INIT_54(SM_INIT_54), .INIT_55(SM_INIT_55),
        .INIT_56(SM_INIT_56), .INIT_58(SM_INIT_58), .INIT_5C(SM_INIT_5C)
    ) u_sysmon (
        .DCLK(clk), .DEN(1'b0), .DWE(1'b0), .DADDR(8'h00), .DI(16'h0000), .DO(), .DRDY(),
        .RESET(1'b0), .CONVST(1'b0), .CONVSTCLK(1'b0), .VP(1'b0), .VN(1'b0), .VAUXP(16'h0000), .VAUXN(16'h0000),
        .ALM(alm), .OT(ot), .BUSY(), .CHANNEL(), .EOC(), .EOS(), .JTAGBUSY(), .JTAGLOCKED(), .JTAGMODIFIED(),
        .MUXADDR(), .ADC_DATA(), .I2C_SCLK(1'b1), .I2C_SDA(1'b1), .I2C_SCLK_TS(), .I2C_SDA_TS(), .SMBALERT_TS());
    assign alarm = {ot, alm[3:0]};
`else
    assign alarm = sim_alarm;
`endif
    b196_shutdown #(.N(5)) u_shutdown (.clk, .rst, .alarm, .shutdown, .cause);
endmodule
